SELECT
  d.id,
  d.defect_date,
  i.item_name,
  d.defect_qty
FROM defects d
LEFT JOIN items i ON d.item_id = i.id


    d.item_id = #{criteria.itemId}


    AND d.defect_date >= #{criteria.fromDate}


    AND d.defect_date <= #{criteria.toDate}


ORDER BY d.id DESC

  LIMIT #{criteria.limit} OFFSET #{criteria.offset}
